#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int main() {
    int N;
    long long K;
    scanf("%d %lld", &N, &K);
    int A[N];
    long long sum = 0;
    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
        sum += A[i];
    }

    long long ans = 1;
    // Check divisors of sum
    for (long long d = 1; d * d <= sum; d++) {
        if (sum % d == 0) {
            // test d
            long long rem[N];
            long long total = 0;
            for (int i = 0; i < N; i++) {
                rem[i] = A[i] % d;
                total += rem[i];
            }
            qsort(rem, N, sizeof(long long), cmp);
            long long need = total / d; // how many to raise to next multiple
            long long moves = 0;
            for (int i = 0; i < N - need; i++) {
                moves += rem[i];
            }
            if (moves <= K && d > ans) ans = d;

            // test sum/d
            long long d2 = sum / d;
            long long rem2[N];
            total = 0;
            for (int i = 0; i < N; i++) {
                rem2[i] = A[i] % d2;
                total += rem2[i];
            }
            qsort(rem2, N, sizeof(long long), cmp);
            long long need2 = total / d2;
            long long moves2 = 0;
            for (int i = 0; i < N - need2; i++) {
                moves2 += rem2[i];
            }
            if (moves2 <= K && d2 > ans) ans = d2;
        }
    }

    printf("%lld\n", ans);
    return 0;
}

