typedef long long ll;

int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    ll K;
    if (scanf("%d %lld", &N, &K) != 2) return 0;

    ll *A = (ll *)malloc(sizeof(ll) * N);
    ll sum = 0;
    for (int i = 0; i < N; i++) {
        scanf("%lld", &A[i]);
        sum += A[i];
    }

    /* enumerate divisors of sum */
    ll *divs = (ll *)malloc(sizeof(ll) * (2 * 100000 + 10));
    int dcnt = 0;
    for (ll d = 1; d * d <= sum; d++) {
        if (sum % d == 0) {
            divs[dcnt++] = d;
            if (d * d != sum) divs[dcnt++] = sum / d;
        }
    }
    qsort(divs, dcnt, sizeof(ll), cmp_ll);

    ll *r = (ll *)malloc(sizeof(ll) * N);
    ll *pref = (ll *)malloc(sizeof(ll) * (N + 1));

    ll ans = 1;

    for (int idx = dcnt - 1; idx >= 0; idx--) {
        ll x = divs[idx];

        for (int i = 0; i < N; i++) r[i] = A[i] % x;
        qsort(r, N, sizeof(ll), cmp_ll);

        pref[0] = 0;
        for (int i = 0; i < N; i++) pref[i + 1] = pref[i] + r[i];

        /* 
           Choose first t elements to decrease to 0 (cost = pref[t]),
           remaining to increase to x (cost = (N-t)*x - (pref[N]-pref[t])).
           These two costs are equal when feasible because total remainder sum is multiple of x.
        */
        for (int t = 0; t <= N; t++) {
            ll dec = pref[t];
            ll inc = (ll)(N - t) * x - (pref[N] - pref[t]);
            if (dec == inc && dec <= K) {
                ans = x;
                printf("%lld\n", ans);
                free(A);
                free(divs);
                free(r);
                free(pref);
                return 0;
            }
        }
    }

    printf("%lld\n", ans);

    free(A);
    free(divs);
    free(r);
    free(pref);
    return 0;
}

