        if (S % d == 0) {
            divisors.push_back(d);
            if (d * d != S) divisors.push_back(S / d);
        }
    }

    sort(divisors.rbegin(), divisors.rend());

    for (int64 x : divisors) {
        vector<int64> r(N);
        for (int i = 0; i < N; ++i) r[i] = A[i] % x;
        sort(r.begin(), r.end());

        vector<int64> pref(N + 1, 0);
        for (int i = 0; i < N; ++i) pref[i + 1] = pref[i] + r[i];

        bool ok = false;
        for (int t = 0; t <= N; ++t) {
            // Make first t numbers decrease to previous multiple of x
            int64 dec = pref[t];
            // Make remaining numbers increase to next multiple of x
            int64 inc = (int64)(N - t) * x - (pref[N] - pref[t]);

            if (dec == inc && dec <= K) {
                ok = true;
                break;
            }
        }

        if (ok) {
            cout << x << '\n';
            return 0;
        }
