public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long K = sc.nextLong();
        long[] A = new long[N];
        long sum = 0;
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextLong();
            sum += A[i];
        }

        long ans = 1;
        for (long g = 1; g * g <= sum; g++) {
            if (sum % g == 0) {
                if (check(A, N, K, g)) ans = Math.max(ans, g);
                long other = sum / g;
                if (other != g && check(A, N, K, other)) ans = Math.max(ans, other);
            }
        }
        System.out.println(ans);
    }

    static boolean check(long[] A, int N, long K, long g) {
        long[] mods = new long[N];
        for (int i = 0; i < N; i++) {
            mods[i] = A[i] % g;
        }
        Arrays.sort(mods);
        long[] prefix = new long[N + 1];
        for (int i = 0; i < N; i++) {
            prefix[i + 1] = prefix[i] + mods[i];
        }
        long totalModSum = prefix[N];
        // Try split point: first i elements we increase to g, rest decrease to 0
        for (int i = 0; i <= N; i++) {
            long leftSum = prefix[i];
            long rightSum = totalModSum - leftSum;
            long ops = (g * i - leftSum);
            if (rightSum == ops && ops <= K) return true;
        }
        return false;
    }
}

