public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long K = fs.nextLong();
        long[] A = new long[N];
        long sum = 0;
        for (int i = 0; i < N; i++) {
            A[i] = fs.nextLong();
            sum += A[i];
        }

        ArrayList<Long> divisors = new ArrayList<>();
        for (long d = 1; d * d <= sum; d++) {
            if (sum % d == 0) {
                divisors.add(d);
                if (d * d != sum) divisors.add(sum / d);
            }
        }

        Collections.sort(divisors, Collections.reverseOrder());

        for (long x : divisors) {
            long[] r = new long[N];
            for (int i = 0; i < N; i++) r[i] = A[i] % x;
            Arrays.sort(r);

            long[] prefix = new long[N + 1];
            for (int i = 0; i < N; i++) prefix[i + 1] = prefix[i] + r[i];

            for (int t = 0; t <= N; t++) {
                long dec = prefix[t]; // decrease these to lower multiple
                long inc = x * (N - t) - (prefix[N] - prefix[t]); // increase these to upper multiple
                if (dec == inc && dec <= K) {
                    System.out.println(x);
                    return;
                }
            }
        }
    }
}
